def _find_historical(hist: dict, rec: dict, feature: str, batch_id: str, kind: str,
                     plan_sha: str, plan_path: str, src_pr):
    """Find the single historical entry binding THIS exact case:
    batch_id + feature + artifact(type,id) + original source PR + ONE kind +
    full plan identity (sha 40hex + path). No cross-batch/kind/plan borrowing."""
    ev = rec.get("evidence") or {}
    for e in hist.get("entries", []):
        if str(e.get("batch_id", "")) != batch_id:
            continue
        if str(e.get("feature", "")).upper()[:2] != feature:
            continue
        if e.get("artifact_type") != ev.get("type") or str(e.get("artifact_id")) != str(ev.get("id")):
            continue
